INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_ADJECTIVE','Boundless');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_ANY','Any');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_ASSIGN','Assign');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_AUTO','Automatic');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_AUTOMATONS','Native automatons: {1_Num}. These are separate from population; remote credits are suspended.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_BALANCED','Balanced');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_BONUS','Registry territorial Culture');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_BONUS_HELP','Automatically maintained by The Grand Registry.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CAPACITY','Remote citizens use forced native labourers or a governor-proof surplus. Available citizens and additional safe remote capacity differ. Pending requests wait for capacity. Specialists remain native. See the guide for remaining engine restrictions.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CAPITAL','The Heart of the World');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CAPITAL_LOST','The Heart of the World is occupied. Surviving units can besiege and reclaim it. Frontier and remote work pause until it returns.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CIV','The Boundless City');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CIV_PEDIA','There shall be no second city. For the first shall have no end.[NEWLINE][NEWLINE]The Boundless City measures civilization in streets, bridges and the citizens who walk them. Every new frontier becomes another district of the same capital. Its one production queue and one population remain the price of that ambition.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CLOSE','Close');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_CULTURE','Culture');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DAWN','There shall be no second city. For the first shall have no end.[NEWLINE][NEWLINE]First Architect, the foundations are laid. Grow the Heart of the World, send your Surveyors beyond the familiar streets, and let every bridge join another district to your one great city.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DEMOLISH','Demolish');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DEMOLISHED','A besieged settlement was demolished through its current owner’s native legal operation. No city or territory was acquired.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DIRECTION','Direction');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DISABLED','The saved Boundless state is invalid or newer than this mod. Remote yields have been removed. Consult Lua.log before continuing.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_DISTANCE','Distance');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_EAST','East');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_EXTRA_REMOVED','An unexpected additional settlement was removed after native razing checks allowed it. Its acquired plots were released; no additional city was retained.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_FAITH','Faith');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_FOOD','Food');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_GOLD','Gold');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_HYBRID','Hybrid');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_IMPROVEMENT','Improvement');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LEADER','The First Architect');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LEADER_PEDIA','The First Architect is an original fictional master builder. Their vision unites settlement, coast and distant island within one continuously growing city. Infrastructure and patient defense matter more than occupation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LOCATE','Locate');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_LOCK','Lock');
