INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_5','Registry Envoy 5');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_6','Registry Envoy 6');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_7','Registry Envoy 7');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_8','Registry Envoy 8');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SPY_9','Registry Envoy 9');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_STRATEGY','Grow your capital, build The Grand Registry, and use Surveyors to develop the frontier. Choose remote tiles in The Boundless Workforce. Science, Culture and Diplomatic victories use normal rules. Subjugate every rival original capital through siege to win Domination without occupation.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SUBJUGATE','Subjugate');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SUBJUGATED','Settlement subjugated once. Ownership is unchanged; no economic reward.');
INSERT OR REPLACE INTO Language_en_US(Tag,Text) VALUES ('TXT_KEY_BC_SUBJUGATION_PROGRESS','Original capitals subjugated: {1_Num} / {2_Num}.');
